def perform_action(self, action, quiet=None):        
        self.currentPipeline.performAction(action)
        self.currentVersion = action.db_id
        self.setChanged(True)

        if quiet is None:
            if not self.quiet:
                self.invalidate_version_tree()
        else:
            if not quiet:
                self.invalidate_version_tree()
        return action.db_id

